import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Map<String, Long> jami = new TreeMap<>();
        while (in.hasNext()) {
            String hudud = in.next(), tovar = in.next();
            long summa = in.nextLong();
            jami.merge(hudud, summa, Long::sum);
        }
        for (String h : jami.keySet()) {
            System.out.println(h + ": " + jami.get(h));
        }
    }
}

solution.cpp:
#include <iostream>
#include <map>
#include <string>
using namespace std;

int main() {
    map<string, long long> jami;
    string hudud, tovar;
    long long summa;
    while (cin >> hudud >> tovar >> summa) {
        jami[hudud] += summa;
    }
    for (auto& p : jami) {
        cout << p.first << ": " << p.second << "\n";
    }
    return 0;
}
